ON CONFLICT (name, (COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid))) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, level = EXCLUDED.level, is_active = EXCLUDED.is_active, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at, requires_2fa = EXCLUDED.requires_2fa, is_system_role = EXCLUDED.is_system_role, tenant_id = EXCLUDED.tenant_id, is_admin_role = EXCLUDED.is_admin_role, system_tag_id = EXCLUDED.system_tag_id, elegivel_plantonista = EXCLUDED.elegivel_plantonista;


-- 7) user_tenant_membership (resolve admxyz + a role acima dinamicamente na VPS)
INSERT INTO public.user_tenant_membership (user_id, tenant_id, role_id, is_active, is_owner, joined_at, is_plantonista)
SELECT u.id, 'b97b25b1-0f04-4cf6-8a59-12c49dcbafeb'::uuid, r.id, true, false, now(), false
FROM public.users u, public.user_roles r
WHERE u.username = 'admxyz'
  AND r.name = 'Administrador' AND r.tenant_id = 'b97b25b1-0f04-4cf6-8a59-12c49dcbafeb'::uuid
ON CONFLICT (user_id, tenant_id) DO UPDATE SET role_id = EXCLUDED.role_id, is_active = true;


COMMIT;

